// Generated by vibelang from src/server/instanceEnvironment.ts; the migrate flow writes it again with each batch.
import * as HostProcess from "@t3tools/shared/HostProcess";
import * as Effect from "effect/Effect";
import { expandHomePath } from "./pathExpansion.js";
export const mergeProviderInstanceEnvironment = Effect.fn(function* (environment, baseEnv = process.env) {
    if (!environment || environment.length === 0) {
        return baseEnv;
    }
    const home = yield* HostProcess.HomeDirectory;
    const next = { ...baseEnv };
    for (const variable of environment) {
        next[variable.name] =
            variable.name === "CODEX_HOME" || variable.name === "CLAUDE_CONFIG_DIR"
                ? expandHomePath(variable.value, home)
                : variable.value;
    }
    return next;
});
